CREATE OR REPLACE FUNCTION public.calculate_investing_dna(p_assessment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_questionnaire_version text; v_model_version text; v_scoring_version text; v_expected_count integer; v_answered_count integer; v_invalid_count integer;
  v_tolerance numeric:=0; v_capacity numeric:=0; v_t_weight numeric:=0; v_c_weight numeric:=0; v_archetype text; v_behavior jsonb:='{}'::jsonb; v_experience jsonb:='{}'::jsonb; v_result_id bigint;
  v_loss numeric; v_reserve numeric; v_raw_capacity numeric; v_products jsonb;
  v_t_low numeric:=33.3334; v_t_high numeric:=66.6667; v_c_low numeric:=33.3334; v_c_high numeric:=66.6667;
begin
 select questionnaire_version,coalesce(model_version,questionnaire_version,'v1'),coalesce(scoring_version,model_version,questionnaire_version,'v1') into v_questionnaire_version,v_model_version,v_scoring_version from public.assessments where id=p_assessment_id;
 if v_questionnaire_version is null then raise exception 'Assessment % does not exist',p_assessment_id; end if;
 if v_scoring_version in ('dna-v1.2','scoring-v1.2') or v_model_version in ('dna-v1.2') then v_t_low:=53; v_t_high:=62; v_c_low:=51.5; v_c_high:=62; end if;
 if v_scoring_version in ('dna-v1.3','scoring-v1.3') or v_model_version in ('dna-v1.3') then v_t_low:=40; v_t_high:=70; v_c_low:=40; v_c_high:=70; end if;
 if (v_questionnaire_version like 'v1.9-%' or v_questionnaire_version like 'v1.10-%') or v_model_version like 'dna-v1.9-%' or v_scoring_version like 'scoring-v1.9-%' then v_t_low:=40; v_t_high:=70; v_c_low:=40; v_c_high:=70; end if;
 select count(*) into v_expected_count from public.question_bank where version=v_questionnaire_version and active=true;
 select count(distinct a.question_id) into v_answered_count from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version and q.active=true where a.assessment_id=p_assessment_id;
 if v_answered_count<>v_expected_count then raise exception 'Assessment % is incomplete: % of % required questions answered',p_assessment_id,v_answered_count,v_expected_count; end if;
 if exists(select 1 from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version where a.assessment_id=p_assessment_id and q.question_type='multi_choice' and (jsonb_typeof(a.answer_value->'value') is distinct from 'array')) then raise exception 'Invalid multiple-choice answer'; end if;
 if exists(select 1 from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version where a.assessment_id=p_assessment_id and q.question_type='multi_choice' and (
 jsonb_array_length(a.answer_value->'value')=0 or
 (a.answer_value->'value' ? 'none' and jsonb_array_length(a.answer_value->'value')>1) or
 exists(select 1 from jsonb_array_elements_text(a.answer_value->'value') v where not exists(select 1 from jsonb_array_elements(q.options)o where o->>'value'=v)) or
 (select count(distinct v) from jsonb_array_elements_text(a.answer_value->'value')v)<>jsonb_array_length(a.answer_value->'value'))) then raise exception 'Invalid product-exposure choices';end if;
 with scored as (
   select q.section,q.construct,q.weight q_weight,coalesce(d.weight,1) d_weight,
          case when q.question_type='multi_choice' then 0 when q.question_type='scale' then
            case when (a.answer_value->>'value')~'^[-+]?[0-9]+(\.[0-9]+)?$' and (a.answer_value->>'value')::numeric between 0 and 10
              then case when q.scoring->'scale'->>'direction'='reverse' then 100-((a.answer_value->>'value')::numeric*10) else ((a.answer_value->>'value')::numeric*10) end
              else null end
          else case when q.scoring ? (a.answer_value->>'value') then (q.scoring->>(a.answer_value->>'value'))::numeric else null end end score
   from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version and q.active=true
   left join public.scoring_dimensions d on d.version=v_questionnaire_version and d.dimension_key=q.construct
   where a.assessment_id=p_assessment_id
 ), invalid as (select count(*) filter(where score is null or score<0 or score>100) n from scored)
 select n into v_invalid_count from invalid;
 if v_invalid_count>0 then raise exception 'Assessment % contains % invalid answer value(s)',p_assessment_id,v_invalid_count; end if;
 with scored as (
   select q.section,q.construct,q.weight q_weight,coalesce(d.weight,1) d_weight,
          case when q.question_type='multi_choice' then 0 when q.question_type='scale' then case when q.scoring->'scale'->>'direction'='reverse' then 100-((a.answer_value->>'value')::numeric*10) else ((a.answer_value->>'value')::numeric*10) end
               else (q.scoring->>(a.answer_value->>'value'))::numeric end score
   from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version and q.active=true
   left join public.scoring_dimensions d on d.version=v_questionnaire_version and d.dimension_key=q.construct
   where a.assessment_id=p_assessment_id
 )
 select coalesce(sum(score*q_weight*d_weight) filter(where section='risk_tolerance'),0),coalesce(sum(q_weight*d_weight) filter(where section='risk_tolerance'),0),coalesce(sum(score*q_weight*d_weight) filter(where section='risk_capacity'),0),coalesce(sum(q_weight*d_weight) filter(where section='risk_capacity'),0)
 into v_tolerance,v_t_weight,v_capacity,v_c_weight from scored where score between 0 and 100;
 if v_t_weight=0 or v_c_weight=0 then raise exception 'Missing risk scoring dimensions for assessment %',p_assessment_id; end if;
 v_tolerance:=round(v_tolerance/v_t_weight,2); v_capacity:=round(v_capacity/v_c_weight,2);
 v_raw_capacity:=v_capacity;
 if v_questionnaire_version like 'v1.10-%' then
 select min((q.scoring->>(a.answer_value->>'value'))::numeric) filter(where q.construct='loss_impact'), min((q.scoring->>(a.answer_value->>'value'))::numeric) filter(where q.construct='emergency_reserve') into v_loss,v_reserve
 from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version where a.assessment_id=p_assessment_id and q.section='risk_capacity';
 if v_loss<=33 or v_reserve=0 then v_capacity:=least(v_capacity,39);end if;
 end if;
 if v_tolerance<v_t_low then if v_capacity<v_c_low then v_archetype:='VAULT'; elsif v_capacity<v_c_high then v_archetype:='ANCHOR'; else v_archetype:='COOLHAND'; end if;
 elsif v_tolerance<v_t_high then if v_capacity<v_c_low then v_archetype:='SCOUT'; elsif v_capacity<v_c_high then v_archetype:='MAVERICK'; else v_archetype:='STRIKER'; end if;
 else if v_capacity<v_c_low then v_archetype:='HOTSHOT'; elsif v_capacity<v_c_high then v_archetype:='HIGHROLLER'; else v_archetype:='JACKPOT'; end if; end if;
 with behavioral as (
   select q.construct,round(avg(case when q.question_type='multi_choice' then 0 when q.question_type='scale' then case when q.scoring->'scale'->>'direction'='reverse' then 100-((a.answer_value->>'value')::numeric*10) else ((a.answer_value->>'value')::numeric*10) end else (q.scoring->>(a.answer_value->>'value'))::numeric end),2) score
   from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version and q.active=true
   where a.assessment_id=p_assessment_id and q.section='behavioral_dna' group by q.construct
 ) select coalesce(jsonb_object_agg(construct,score),'{}'::jsonb) into v_behavior from behavioral;
 with exp as (
   select q.construct,round(avg((q.scoring->>(a.answer_value->>'value'))::numeric),2) score
   from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version and q.active=true
   where a.assessment_id=p_assessment_id and q.section='investment_experience' and q.question_type<>'multi_choice' and q.scoring ? (a.answer_value->>'value')
   group by q.construct
 ), eagg as (
   select coalesce(jsonb_object_agg(construct,score),'{}'::jsonb) dimensions,
          case when count(*)>0 then round(avg(score)/3*100,2) else null end overall_score
   from exp
 ) select case when overall_score is null then '{}'::jsonb else jsonb_build_object('dimensions',dimensions,'overall_score',overall_score,'role','context_only') end into v_experience from eagg;
 select a.answer_value->'value' into v_products from public.answers a join public.question_bank q on q.question_id=a.question_id and q.version=v_questionnaire_version where a.assessment_id=p_assessment_id and q.construct='product_exposure' and q.question_type='multi_choice';
 if v_products is not null then v_experience:=v_experience||jsonb_build_object('owned_products',v_products,'score_basis','decision_and_downturn_experience_only');end if;
 update public.results set risk_tolerance=v_tolerance,risk_capacity=v_capacity,archetype=v_archetype,behavioral_profile=v_behavior,experience_profile=v_experience,scoring_version=v_scoring_version,narrative='{}'::jsonb,created_at=now() where assessment_id=p_assessment_id and model_version=v_model_version returning id into v_result_id;
 if v_result_id is null then insert into public.results(assessment_id,model_version,risk_tolerance,risk_capacity,archetype,behavioral_profile,experience_profile,narrative,scoring_version) values(p_assessment_id,v_model_version,v_tolerance,v_capacity,v_archetype,v_behavior,v_experience,'{}'::jsonb,v_scoring_version) returning id into v_result_id; end if;
 if v_questionnaire_version like 'v1.10-%' then
 update public.results set capacity_profile=jsonb_build_object('raw_index',v_raw_capacity,'guarded_capacity',v_capacity,'review_required',coalesce(v_loss<=33 or v_reserve=0,false),'reason',case when v_loss<=33 then 'A loss could disrupt essential spending or commitments.' when v_reserve=0 then 'Emergency savings cover less than one month.' else null end) where id=v_result_id;
 end if;
 update public.assessments set model_version=v_model_version,scoring_version=v_scoring_version,status='completed',completed_at=coalesce(completed_at,now()) where id=p_assessment_id;
 return jsonb_build_object('result_id',v_result_id,'capacity_profile',(select capacity_profile from public.results where id=v_result_id),'risk_tolerance',v_tolerance,'risk_capacity',v_capacity,'archetype',v_archetype,'behavioral_profile',v_behavior,'experience_profile',v_experience,'questionnaire_version',v_questionnaire_version,'model_version',v_model_version,'scoring_version',v_scoring_version,'calibration_status',case when (v_questionnaire_version like 'v1.9-%' or v_questionnaire_version like 'v1.10-%') then 'pre_validation' else 'legacy' end,'boundaries',jsonb_build_object('tolerance_low',v_t_low,'tolerance_high',v_t_high,'capacity_low',v_c_low,'capacity_high',v_c_high));
end;
$function$;

CREATE OR REPLACE FUNCTION public.generate_investing_narrative(p_assessment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
 r public.results%rowtype; f public.fingerprint_profiles%rowtype; n jsonb:='{}'::jsonb; v_questionnaire text; v_model text;
 archetype_name text; summary text; thinking text; pressure text; strength text; blind text; influence text; character text; method_note text;
 v_strength_key text; v_watch_key text;
begin
 select questionnaire_version,coalesce(model_version,questionnaire_version) into v_questionnaire,v_model from public.assessments where id=p_assessment_id;
 select * into r from public.results where assessment_id=p_assessment_id order by created_at desc limit 1;
 if r.id is null then raise exception 'No result found for assessment'; end if;
 select * into f from public.fingerprint_profiles where assessment_id=p_assessment_id order by created_at desc limit 1;
 if f.id is null then raise exception 'Fingerprint must be generated before narrative'; end if;
 select display_name into archetype_name from public.archetype_profiles where version=v_questionnaire and archetype_key=r.archetype limit 1;
 if archetype_name is null then select display_name into archetype_name from public.archetype_profiles where version='v1.1' and archetype_key=r.archetype limit 1; end if;
 summary:=case r.archetype
  when 'VAULT' then 'You currently show a lower willingness to take investment risk and lower financial room to absorb losses.'
  when 'ANCHOR' then 'You currently show a lower willingness to take investment risk with a moderate financial ability to absorb losses.'
  when 'COOLHAND' then 'You currently show a lower willingness to take investment risk even though your financial capacity is relatively stronger.'
  when 'SCOUT' then 'You currently show a moderate willingness to take investment risk while your financial capacity is more constrained.'
  when 'MAVERICK' then 'You currently show a middle-range combination of willingness to take risk and financial capacity.'
  when 'STRIKER' then 'You currently show a moderate willingness to take investment risk with relatively stronger financial capacity.'
  when 'HOTSHOT' then 'You currently show a higher willingness to take investment risk than your financial capacity may support.'
  when 'HIGHROLLER' then 'You currently show a higher willingness to take investment risk with moderate financial capacity.'
  when 'JACKPOT' then 'You currently show both higher willingness to take investment risk and stronger financial capacity.'
  else 'Your profile reflects a distinct combination of risk tolerance, financial capacity and behavioral tendencies.' end;
 thinking:=case f.decision_style
  when 'Evidence-Led' then 'You tend to test investment ideas against evidence and your own criteria rather than relying mainly on enthusiasm or prior conviction.'
  when 'Plan-Driven' then 'You tend to stay anchored to your plan and time horizon unless new evidence changes the investment case.'
  when 'Socially Responsive' then 'Enthusiasm from people you trust can pull your attention toward an investment before your own process is complete.'
  when 'High-Conviction' then 'Once you like an investment idea, your original view can remain influential even when new evidence challenges it.'
  when 'Performance-Sensitive' then 'Recent winners and laggards can influence how attractive an investment feels to you.'
  when 'Reference-Sensitive' then 'Past purchase prices and existing gains or losses can influence how you evaluate what to do next.'
  when 'Conviction-Driven' then 'You tend to make decisions from a strong internal thesis and can move with conviction once the case feels compelling.'
  when 'Adaptive' then 'You are relatively willing to revise your view when new evidence changes the investment case.'
  when 'Socially Influenced' then 'Other investors and their outcomes can meaningfully shape how you evaluate opportunities.'
  when 'Recency-Sensitive' then 'Recent market performance can have a noticeable effect on how attractive an opportunity feels.'
  else 'You tend to combine your own criteria, evidence and experience rather than relying on a single decision cue.' end;
 pressure:=case f.pressure_style
  when 'Composed' then 'Sharp market moves are less likely to pull you away from a decision process you set while calm.'
  when 'Emotion-Sensitive' then 'Sharp market moves can create pressure to change course sooner than you originally intended.'
  when 'Emotionally Reactive' then 'Under pressure, emotions can make it harder to follow a pre-planned strategy.'
  when 'Adaptive Under Pressure' then 'Under pressure, you tend to reassess quickly and adjust when the evidence warrants it.'
  else 'Your response to market pressure appears mixed rather than strongly reactive or strongly composed.' end;
 v_strength_key:=f.strengths->>0; v_watch_key:=f.watchouts->>0;
 strength:=case v_strength_key
  when 'decision_independence' then 'A relative strength is separating other people’s enthusiasm from your own investment decision.'
  when 'long_term_orientation' then 'A relative strength is keeping recent performance in perspective when thinking about long-term decisions.'
  when 'reference_flexibility' then 'A relative strength is reassessing an investment from today forward rather than staying anchored to the price you paid.'
  when 'evidence_discipline' then 'A relative strength is being willing to test a favored idea against new or conflicting evidence.'
  when 'emotional_decision_control' then 'A relative strength is maintaining decision discipline when markets or regret create emotional pressure.'
  else 'No single behavioral dimension dominates strongly enough yet to call it a clear strength.' end;
 blind:=case v_watch_key
  when 'decision_independence' then 'A watchpoint is that trusted people or market enthusiasm may influence your interest before your own analysis is complete.'
  when 'long_term_orientation' then 'A watchpoint is that recent performance may pull attention away from the original thesis or time horizon.'
  when 'reference_flexibility' then 'A watchpoint is that the price you paid or an existing gain or loss may influence decisions more than the outlook from today.'
  when 'evidence_discipline' then 'A watchpoint is that strong conviction may make conflicting evidence harder to incorporate.'
  when 'emotional_decision_control' then 'A watchpoint is that sharp market moves or regret may create pressure to change course sooner than planned.'
  else 'No single behavioral watchpoint is strong enough yet to stand out clearly.' end;
 influence:='The behavioral dimensions describe how decisions may be shaped by social influence, recent performance, reference points, evidence and emotion. They do not change your financial risk capacity score.';
 character:=case r.archetype when 'VAULT' then 'The Capital Protector' when 'ANCHOR' then 'The Steady Builder' when 'COOLHAND' then 'The Calm Conservative' when 'SCOUT' then 'The Cautious Explorer' when 'MAVERICK' then 'The Balanced Risk Taker' when 'STRIKER' then 'The Calculated Aggressor' when 'HOTSHOT' then 'The High-Risk Aspirant' when 'HIGHROLLER' then 'The High-Conviction Investor' when 'JACKPOT' then 'The Adaptive Risk Taker' else 'The Investor' end;
 method_note:=case when (v_questionnaire like 'v1.9-%' or v_questionnaire like 'v1.10-%') then 'Pre-validation research output. Questionnaire wording, cut points and response-consistency rules remain provisional until cognitive testing and a real pilot are completed.' else null end;
 n:=jsonb_build_object('archetype',r.archetype,'archetype_name',archetype_name,'summary',summary,'how_you_think',thinking,'pressure_style',pressure,'strength',strength,'blind_spot',blind,'decision_influence',influence,'character',character,'risk_tolerance',r.risk_tolerance,'risk_capacity',r.risk_capacity,'behavioral_fingerprint',f.trait_scores,'experience_profile',r.experience_profile,'quality_profile',r.quality_profile,'methodology_note',method_note);
 insert into public.narratives(assessment_id,model_version,narrative) values(p_assessment_id,'narrative-'||v_model,n) on conflict(assessment_id,model_version) do update set narrative=excluded.narrative;
 return n;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_report_snapshot(p_assessment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare r public.results%rowtype; f public.fingerprint_profiles%rowtype; n public.narratives%rowtype; c public.investment_context%rowtype; p jsonb; rid uuid; v_report_version text;
begin
 select * into r from public.results where assessment_id=p_assessment_id order by created_at desc limit 1;
 if not found then raise exception 'Result not found for assessment %',p_assessment_id; end if;
 select * into f from public.fingerprint_profiles where assessment_id=p_assessment_id order by created_at desc limit 1;
 if not found then raise exception 'Fingerprint not found for assessment %',p_assessment_id; end if;
 select * into n from public.narratives where assessment_id=p_assessment_id order by created_at desc limit 1;
 if not found then raise exception 'Narrative not found for assessment %',p_assessment_id; end if;
 select * into c from public.investment_context where assessment_id=p_assessment_id limit 1;
 v_report_version:=case when r.model_version like 'dna-v1.10-%' then 'report-v1.4' else case when r.model_version like 'dna-v1.9-%' then 'report-v1.3' else 'report-v1.2' end end;
 p := jsonb_build_object('assessment_id',p_assessment_id,'report_version',v_report_version,'model_version',r.model_version,'generated_at',now(),'archetype',r.archetype,'risk_tolerance',r.risk_tolerance,'risk_capacity',r.risk_capacity,'capacity_profile',r.capacity_profile,'behavioral_profile',r.behavioral_profile,'experience_profile',r.experience_profile,'quality_profile',r.quality_profile,'fingerprint_code',f.fingerprint_code,'decision_style',f.decision_style,'pressure_style',f.pressure_style,'strengths',f.strengths,'watchouts',f.watchouts,'narrative',n.narrative,'investment_context',case when c.id is null then null else jsonb_build_object('first_name',c.first_name,'age',c.age,'amount_to_invest',c.amount_to_invest,'amount_currency',c.amount_currency,'goal',c.goal,'time_horizon',c.time_horizon,'horizon_months',c.horizon_months,'principal_required',c.principal_required,'investment_share',c.investment_share,'liquidity_need',c.liquidity_need,'required_return',c.required_return,'loss_consequence',c.loss_consequence,'experience',c.experience) end);
 insert into public.report_snapshots(assessment_id,report_version,model_version,report) values(p_assessment_id,v_report_version,r.model_version,p) on conflict (assessment_id,report_version,model_version) do update set report=excluded.report,generated_at=now() returning id into rid;
 return jsonb_build_object('id',rid,'report',p);
end;
$function$;


-- Related facets are not logical consistency checks. Only two repeated-risk pairs
-- remain exploratory; response repetition is a separate, non-diagnostic signal.
create or replace function public.calculate_assessment_quality(p_assessment_id uuid)
returns jsonb language plpgsql set search_path='' as $$
declare v_version text; v_model text; pairs jsonb; n int; repeated boolean; quality jsonb;
begin
 select questionnaire_version,model_version into v_version,v_model from public.assessments where id=p_assessment_id;
 with s as (select q.question_id,(q.scoring->>(a.answer_value->>'value'))::numeric score from public.answers a join public.question_bank q on q.version=v_version and q.question_id=a.question_id where a.assessment_id=p_assessment_id and q.question_type='single_choice'),
 p as (select a.question_id q1,b.question_id q2,abs(a.score-b.score) difference from s a join s b on (a.question_id,b.question_id) in (('RT01','RT02'),('RT09','RT10')))
 select coalesce(jsonb_agg(jsonb_build_object('q1',q1,'q2',q2,'difference',difference,'status',case when difference>=67 then 'discuss' else 'related' end)),'[]'),count(*) filter(where difference>=67) into pairs,n from p;
 select count(*)>=10 and count(distinct a.answer_value->>'value')=1 into repeated from public.answers a join public.question_bank q on q.version=v_version and q.question_id=a.question_id where a.assessment_id=p_assessment_id and q.section in ('risk_tolerance','behavioral_dna') and q.question_type<>'multi_choice';
 quality:=jsonb_build_object('supported',true,'heuristic_version','response-review-v1','pair_count',jsonb_array_length(pairs),'pairs',pairs,'conflict_count',n,'consistency_label',case when n>0 then 'discussion_suggested' else 'not_validated' end,'clarification_recommended',n>0,'repeated_position_pattern',repeated,'note','Related answers are discussion prompts, not contradictions. Repeated choices and agreement do not prove response quality. This signal does not change risk scores.');
 update public.results set quality_profile=quality where assessment_id=p_assessment_id and model_version=v_model;
 return quality;
end; $$;

create or replace function public.complete_dna_assessment(p_assessment_id uuid)
returns jsonb language plpgsql set search_path='' as $$
declare a public.assessments; r jsonb; q jsonb; f jsonb; n jsonb; report jsonb; m jsonb; b jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_assessment_id::text,600));
 select * into a from public.assessments where id=p_assessment_id for update;
 if a.id is null or a.status not in ('in_progress','completed') then raise exception 'assessment_unavailable';end if;
 if a.status='in_progress' then r:=public.calculate_investing_dna(p_assessment_id);
 else select to_jsonb(x) into r from public.results x where assessment_id=p_assessment_id order by created_at desc,id desc limit 1; end if;
 if r is null then raise exception 'dna_result_not_found';end if;
 q:=public.calculate_assessment_quality(p_assessment_id);f:=public.calculate_investing_fingerprint(p_assessment_id);n:=public.generate_investing_narrative(p_assessment_id);
 if a.profile_id is not null then perform public.promote_assessment_to_current_dna(p_assessment_id);end if;
 report:=public.create_report_snapshot(p_assessment_id);m:=investor_private.current_match(p_assessment_id);b:=public.generate_portfolio_blueprints(p_assessment_id);
 return jsonb_build_object('result',r||jsonb_build_object('quality_profile',q),'quality',q,'fingerprint',f,'narrative',n,'report',report,'match',m,'portfolio',b,'account_linked',a.profile_id is not null,'language_code',a.language_code);
end; $$;

create or replace function public.service_save_investment_context(p_assessment_id uuid,p_context jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare a public.assessments; c public.investment_context; v_months int; v_time text; v_name text; report jsonb; m jsonb; b jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_assessment_id::text,600));
 select * into a from public.assessments where id=p_assessment_id for update;
 if a.id is null or a.status<>'completed' then raise exception 'Complete your assessment first.';end if;
 if p_context->>'goal' is null or p_context->>'liquidity_need' is null then raise exception 'Choose your goal and access needs.';end if;
 v_months:=(p_context->>'horizon_months')::int;
 if v_months is not null and (v_months<0 or v_months>1200) then raise exception 'Withdrawal horizon must be 0 to 1200 months.';end if;
 v_time:=coalesce(p_context->>'time_horizon',case when v_months<12 then 'lt_1y' when v_months<36 then '1_3y' when v_months<60 then '3_5y' when v_months<120 then '5_10y' else 'gt_10y' end);
 if v_months is null and p_context->>'time_horizon' is null then raise exception 'Choose when you may first need this money.';end if;
 v_name:=nullif(trim(p_context->>'first_name'),'');
 insert into public.investment_context(assessment_id,goal,time_horizon,liquidity_need,horizon_months,principal_required,investment_share,first_name,age,amount_to_invest,amount_currency,required_return,loss_consequence,experience)
 values(p_assessment_id,p_context->>'goal',v_time,p_context->>'liquidity_need',v_months,p_context->>'principal_required',p_context->>'investment_share',v_name,(p_context->>'age')::int,(p_context->>'amount_to_invest')::numeric,'CAD',null,null,null)
 on conflict(assessment_id) do update set goal=excluded.goal,time_horizon=excluded.time_horizon,liquidity_need=excluded.liquidity_need,horizon_months=excluded.horizon_months,principal_required=excluded.principal_required,investment_share=excluded.investment_share,first_name=excluded.first_name,age=excluded.age,amount_to_invest=excluded.amount_to_invest,required_return=null,loss_consequence=null,experience=null,updated_at=clock_timestamp()
 returning * into c;
 report:=public.create_report_snapshot(p_assessment_id);m:=public.calculate_investment_match_v6(p_assessment_id);b:=public.generate_portfolio_blueprints(p_assessment_id);
 return jsonb_build_object('investment_context',to_jsonb(c),'report',report,'match',m,'portfolio',b);
end; $$;

create or replace function public.app_save_investment_context(p_assessment_id uuid,p_context jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not exists(select 1 from public.assessments a join public.profiles p on p.id=a.profile_id where a.id=p_assessment_id and p.user_id=auth.uid()) then raise exception 'assessment_not_owned' using errcode='42501';end if;
 return public.service_save_investment_context(p_assessment_id,p_context);
end; $$;

create or replace function public.get_current_investor_app_state()
returns jsonb language plpgsql security definer set search_path='' as $$
declare p public.profiles; ip public.investor_profiles; report jsonb; m jsonb; b jsonb; r jsonb; c jsonb;
begin
 if auth.uid() is null then raise exception 'authentication_required' using errcode='42501';end if;
 select * into p from public.profiles where user_id=auth.uid() limit 1;
 if p.id is null then return jsonb_build_object('has_profile',false,'dna',null);end if;
 select * into ip from public.investor_profiles where profile_id=p.id limit 1;
 if ip.latest_assessment_id is null then return jsonb_build_object('has_profile',true,'dna',null);end if;
 -- Defense in depth: the latest pointer must belong to the same owned profile.
 if not exists(select 1 from public.assessments where id=ip.latest_assessment_id and profile_id=p.id) then raise exception 'assessment_not_owned' using errcode='42501';end if;
 select to_jsonb(x) into r from public.results x where assessment_id=ip.latest_assessment_id order by created_at desc,id desc limit 1;
 if r is null then return jsonb_build_object('has_profile',true,'dna',null);end if;
 select rs.report into report from public.report_snapshots rs where rs.assessment_id=ip.latest_assessment_id order by rs.generated_at desc,rs.created_at desc limit 1;
 select to_jsonb(x) into c from public.investment_context x where x.assessment_id=ip.latest_assessment_id;
 report:=coalesce(report,r)||jsonb_build_object('investment_context',c,'capacity_profile',r->'capacity_profile');
 m:=investor_private.current_match(ip.latest_assessment_id);b:=public.generate_portfolio_blueprints(ip.latest_assessment_id);
 return jsonb_build_object('authenticated',true,'has_profile',true,'profile_id',p.id,'investor_profile_id',ip.id,'assessment_id',ip.latest_assessment_id,'dna',r,'report',report,'matches',m,'portfolios',b->'blueprints','portfolio_status',b->'status');
end; $$;

grant usage on schema investor_private to service_role;
revoke all on function public.complete_dna_assessment(uuid),public.service_save_investment_context(uuid,jsonb),public.calculate_investing_dna(uuid),public.calculate_assessment_quality(uuid) from public,anon,authenticated;
grant execute on function public.complete_dna_assessment(uuid),public.service_save_investment_context(uuid,jsonb),public.calculate_investing_dna(uuid),public.calculate_assessment_quality(uuid) to service_role;
revoke all on function public.app_save_investment_context(uuid,jsonb),public.get_current_investor_app_state() from public,anon;
grant execute on function public.app_save_investment_context(uuid,jsonb),public.get_current_investor_app_state() to authenticated,service_role;

create or replace function public.service_claim_assessment(p_assessment_id uuid,p_profile_id uuid)
returns jsonb language plpgsql set search_path='' as $$
declare a public.assessments; result jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_assessment_id::text,600));
 select * into a from public.assessments where id=p_assessment_id for update;
 if a.id is null then raise exception 'assessment_not_found';end if;
 if a.profile_id is not null and a.profile_id<>p_profile_id then raise exception 'assessment_already_claimed' using errcode='42501';end if;
 if not exists(select 1 from public.profiles where id=p_profile_id) then raise exception 'profile_not_found';end if;
 update public.assessments set profile_id=p_profile_id where id=p_assessment_id;
 if a.status='completed' then result:=public.complete_dna_assessment(p_assessment_id);else result:='{}';end if;
 return result||jsonb_build_object('claimed',true,'profile_id',p_profile_id,'assessment_id',p_assessment_id);
end; $$;
revoke all on function public.service_claim_assessment(uuid,uuid) from public,anon,authenticated;
grant execute on function public.service_claim_assessment(uuid,uuid) to service_role;
